def mask_url(name: str, stroke_width: float = 2) -> str:
    """The icon as a CSS mask image (black strokes; only the shape matters)."""
    body = (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="black" '
            f'stroke-width="{stroke_width}" stroke-linecap="round" stroke-linejoin="round">{ICONS[name]}</svg>')
    return "url('data:image/svg+xml;charset=utf-8," + quote(body) + "')"


def svg(name: str, size: int = 18, stroke_width: float = 2, cls: str = "") -> str:
    """An icon drawn in the current text colour, like lucide-react's <Icon size strokeWidth />.
    (Streamlit strips <svg> tags from HTML, so the icon is a CSS mask on a <span>.)"""
    return (f'<span class="rg-ic {cls}" aria-hidden="true" style="width:{size}px;height:{size}px;'
            f'--rg-icon:{mask_url(name, stroke_width)}"></span>')
